import{_ as a,o as i,c as e,ag as t}from"./chunks/framework.CvZZEx4j.js";const c=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md","lastUpdated":null}'),r={name:"reference/faq.md"};function o(n,l,s,d,h,g){return i(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="覆盖层不显示" tabindex="-1">覆盖层不显示 <a class="header-anchor" href="#覆盖层不显示" aria-label="Permalink to &quot;覆盖层不显示&quot;">​</a></h2><p><strong>可能原因</strong>：</p><ul><li>未安装酒馆助手插件</li><li>脚本未加载成功（检查控制台是否有报错）</li><li>当前角色卡未开启插件</li></ul><p><strong>解决方法</strong>：</p><ol><li>确认酒馆助手已安装且启用</li><li>检查脚本列表中「galgame界面插件」是否存在且启用</li><li>按 F12 查看控制台是否有加载错误</li></ol><h2 id="ai-不按-galgame-格式输出" tabindex="-1">AI 不按 Galgame 格式输出 <a class="header-anchor" href="#ai-不按-galgame-格式输出" aria-label="Permalink to &quot;AI 不按 Galgame 格式输出&quot;">​</a></h2><p><strong>可能原因</strong>：</p><ul><li>未注入 COT 世界书</li><li>模型能力不足以遵守格式</li></ul><p><strong>解决方法</strong>：</p><ol><li>在设置面板中点击「注入世界书」</li><li>如果仍不行，启用 <a href="/galgame/advanced/enhanced-mode.html">加强模式</a></li></ol><h2 id="立绘-背景不加载" tabindex="-1">立绘/背景不加载 <a class="header-anchor" href="#立绘-背景不加载" aria-label="Permalink to &quot;立绘/背景不加载&quot;">​</a></h2><p><strong>可能原因</strong>：</p><ul><li>未上传对应的资源</li><li>远程资源地址不可访问</li></ul><p><strong>解决方法</strong>：</p><ol><li>检查资源管理器中是否有对应的立绘/背景</li><li>如果使用远程资源，检查 URL 是否可访问</li></ol><h2 id="live2d-模型网络错误" tabindex="-1">Live2D 模型网络错误 <a class="header-anchor" href="#live2d-模型网络错误" aria-label="Permalink to &quot;Live2D 模型网络错误&quot;">​</a></h2><p><strong>可能原因</strong>：</p><ul><li>远程模型 URL 存在跨域（CORS）限制</li><li>网络不稳定</li></ul><p><strong>解决方法</strong>：</p><ol><li>在 Live2D 设置中启用 CORS 代理</li><li>将模型上传到支持跨域的 CDN（如 jsDelivr）</li><li>或改为本地上传模型</li></ol><h2 id="tts-没有声音" tabindex="-1">TTS 没有声音 <a class="header-anchor" href="#tts-没有声音" aria-label="Permalink to &quot;TTS 没有声音&quot;">​</a></h2><p><strong>可能原因</strong>：</p><ul><li>TTS 未启用</li><li>音色未绑定</li><li>GPT-SoVITS 服务未运行</li></ul><p><strong>解决方法</strong>：</p><ol><li>检查设置面板中 TTS 是否开启</li><li>确认角色已绑定音色</li><li>如果使用 GPT-SoVITS，确认本地服务正在运行</li></ol><h2 id="移动端显示异常" tabindex="-1">移动端显示异常 <a class="header-anchor" href="#移动端显示异常" aria-label="Permalink to &quot;移动端显示异常&quot;">​</a></h2><p><strong>说明</strong>： 插件针对桌面浏览器优化，在移动端可能存在布局适配问题。</p><p><strong>建议</strong>：</p><ul><li>使用全屏模式获得更好的体验</li><li>如果弹窗被遮挡，尝试横屏使用</li></ul>',30)])])}const u=a(r,[["render",o]]);export{c as __pageData,u as default};
